/**
 * Trace query fixture IDs generated by the canonical allocators (see fixture.ts).
 * The fixture exercises: general references, supersedes, realization series via
 * augmentation, an index-role hub, a semantics-undefined relation, an isolated
 * requirement, a constraint violation, and a directed reference cycle.
 */
export const T_REQ1 = formatReqId(1)
export const T_REQ2 = formatReqId(2)
export const T_REQ3 = formatReqId(3)
export const T_REQ4 = formatReqId(4)
export const T_REQ5 = formatReqId(5)
export const T_REQ9 = formatReqId(9)
export const T_DEC1 = formatDecisionId(1)
export const T_DEC2 = formatDecisionId(2)

const FEATURE_STEM = "feature"
const FEATURE_MD = `${FEATURE_STEM}.md`
export const NOWHERE_MD = "nowhere.md"

export const SPEC_PATH = `docs/specs/${FEATURE_MD}`
export const SRC_PATH = `src/${FEATURE_STEM}.ts`

export const REQ1_NODE = `requirement:${T_REQ1}`
export const REQ2_NODE = `requirement:${T_REQ2}`
export const REQ3_NODE = `requirement:${T_REQ3}`
export const REQ4_NODE = `requirement:${T_REQ4}`
export const REQ5_NODE = `requirement:${T_REQ5}`
export const DEC1_NODE = `decision:${T_DEC1}`
export const DEC2_NODE = `decision:${T_DEC2}`
export const SPEC_NODE = `specification:${SPEC_PATH}`
export const HUB_NODE = "index_doc:hub.md"
export const SRC_NODE = `source_code:${FEATURE_STEM}.ts`

export function traceAugmentationYaml(options: {
  readonly indexRole: boolean
  readonly relatedLimit?: number
}): string {
  const lines = [
    "node_types:",
    "  - name: source_code",
    '    path_pattern: "^src/([^/]+\\\\.ts)$"',
    '    id_template: "source_code:{match1}"',
    "    label_source:",
    "      - kind: path",
    "    extraction_rule: filesystem",
    "  - name: index_doc",
    '    path_pattern: "^docs/index/([^/]+\\\\.md)$"',
    '    id_template: "index_doc:{match1}"',
    "    label_source:",
    "      - kind: first_heading",
    "    extraction_rule: frontmatter",
  ]
  if (options.indexRole) lines.push("    role: index")
  lines.push(
    "relation_types:",
    "  - name: implemented_by",
    "    fields:",
    "      - implemented_by",
    "    reverse_direction: false",
    "    semantics:",
    '      meaning: "成果物が当該ソースコードによって実装される"',
    "      semantics_slot: implement",
    "      change_impact_direction: forward",
    "      standard_vocabulary: []",
    "  - name: mentioned_in",
    "    fields:",
    "      - mentioned_in",
    "    reverse_direction: false",
    "indexed_paths:",
    "  - src",
    "  - docs/index",
    "discovery_roots:",
    "  - src",
    "query_settings:",
    "  concentration_threshold: 3",
  )
  if (options.relatedLimit !== undefined) {
    lines.push("  limits:", `    related: ${options.relatedLimit}`)
  }
  lines.push(
    "relation_constraints:",
    "  - relation_type: implemented_by",
    "    allowed_source_types:",
    "      - specification",
    "    allowed_target_types:",
    "      - source_code",
  )
  return `${lines.join("\n")}\n`
}

