export async function createTraceFixture(root: string, augmentation: string): Promise<void> {
  for (const [relativePath, content] of Object.entries({ ...FILES, ".agentdev/artifact-graph.yaml": augmentation })) {
    const fullPath = join(root, relativePath)
    await mkdir(join(fullPath, ".."), { recursive: true })
    await writeFile(fullPath, content, "utf8")
  }
}
